describe('Form Validation - Required Fields Highlighting', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should highlight required fields when submitting an empty form', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/form-submit').as('submitForm');

    // Fill in only the email field
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Click the submit button
    cy.get('[data-testid="submit-button"]').click();

    // Verify the form submission was intercepted
    cy.wait('@submitForm').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify the email field is highlighted
    cy.get('[data-testid="email-input"]').should('have.class', 'highlighted');

    // Verify the name field is also highlighted
    cy.get('[data-testid="name-input"]').should('have.class', 'highlighted');

    // Verify the phone field is highlighted
    cy.get('[data-testid="phone-input"]').should('have.class', 'highlighted');

    // Verify the submit button is disabled
    cy.get('[data-testid="submit-button"]').should('be.disabled');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please fill all required fields');
  });

  it('should clear highlighted fields when user corrects them', () => {
    // Fill in only the email field
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Click the submit button
    cy.get('[data-testid="submit-button"]').click();

    // Verify the form submission was intercepted
    cy.wait('@submitForm').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify the email field is highlighted
    cy.get('[data-testid="email-input"]').should('have.class', 'highlighted');

    // Fill in the name field
    cy.get('[data-testid="name-input"]').type('John Doe');

    // Verify the highlighted class is removed from email field
    cy.get('[data-testid="email-input"]').should('not.have.class', 'highlighted');

    // Verify the phone field is still highlighted
    cy.get('[data-testid="phone-input"]').should('have.class', 'highlighted');

    // Verify the submit button is now enabled
    cy.get('[data-testid="submit-button"]').should('not.be.disabled');

    // Verify error message is cleared
    cy.get('[data-testid="error-message"]').should('not.exist');
  });
});
